"use strict";
/* MEGA ROBO — 8-bit side-scrolling platformer demo. Vanilla canvas, WebAudio, zero deps. */
const W = 480, H = 270;
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
ctx.imageSmoothingEnabled = false;

// ---------- sprites (injected base64) ----------
const SPR_B64 = {"hit": "", "idle": "", "jump": "", "run1": "", "run2": "", "shoot": "", "shoot_up": "", "slide": ""};
const SPR = {};
let spritesReady = false;
function loadSprites() {
  const names = Object.keys(SPR_B64);
  let n = 0;
  for (const k of names) {
    const img = new Image();
    img.onload = () => { if (++n === names.length) spritesReady = true; };
    img.src = 'data:image/png;base64,' + SPR_B64[k];
    SPR[k] = img;
  }
}
const BG_B64 = "";
const bgImg = new Image();
bgImg.src = 'data:image/jpeg;base64,' + BG_B64;

// ---------- audio ----------
let AC = null;
function audio() { if (!AC) { AC = new (window.AudioContext || window.webkitAudioContext)(); } if (AC.state === 'suspended') AC.resume(); return AC; }
function beep(freq, dur, type, vol, slideTo) {
  try {
    const ac = audio(), o = ac.createOscillator(), g = ac.createGain();
    o.type = type || 'square'; o.frequency.setValueAtTime(freq, ac.currentTime);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, ac.currentTime + dur);
    g.gain.setValueAtTime(vol || 0.08, ac.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + dur);
    o.connect(g); g.connect(ac.destination);
    o.start(); o.stop(ac.currentTime + dur);
  } catch (e) {}
}
function noiseBurst(dur, vol) {
  try {
    const ac = audio(), len = ac.sampleRate * dur, buf = ac.createBuffer(1, len, ac.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const s = ac.createBufferSource(); s.buffer = buf;
    const g = ac.createGain(); g.gain.value = vol || 0.15;
    s.connect(g); g.connect(ac.destination); s.start();
  } catch (e) {}
}
const SFX = {
  shoot() { beep(880, 0.08, 'square', 0.06, 220); },
  eshoot() { beep(330, 0.12, 'sawtooth', 0.05, 110); },
  jump() { beep(220, 0.12, 'square', 0.06, 660); },
  hurt() { beep(160, 0.25, 'sawtooth', 0.1, 60); },
  explode() { noiseBurst(0.3, 0.18); beep(120, 0.3, 'triangle', 0.1, 40); },
  pickup() { beep(660, 0.07, 'square', 0.06); setTimeout(() => beep(990, 0.1, 'square', 0.06), 70); },
};
// music: simple 8-bar loop, square bass + lead
const MUS_BASS = [110,110,130.8,110, 87.3,87.3,98,87.3];
const MUS_LEAD = [440,523.25,659.25,523.25, 392,440,523.25,440];
let musStep = 0, musTimer = 0;
function musicTick() {
  musTimer++;
  if (musTimer % 14 === 0) {
    const i = musStep % 8;
    beep(MUS_BASS[i], 0.16, 'triangle', 0.045);
    if (musStep % 2 === 0) beep(MUS_LEAD[i], 0.12, 'square', 0.028);
    musStep++;
  }
}

// ---------- input ----------
const keys = {};
addEventListener('keydown', e => { keys[e.code] = true; audio(); if (['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)) e.preventDefault(); });
addEventListener('keyup', e => { keys[e.code] = false; });
const AUTO = new URLSearchParams(location.search).get('auto') === '1';
function pressed(code) { return !!(keys[code]); }

// ---------- touch controls (mobile) ----------
// Per gamepress docs/TOUCH.md: floating stick on left half, circular A/B
// buttons bottom-right, PointerEvent API with distinct pointerIds.
// Self-contained (zero deps): DOM overlay, no canvas drawing, no imports.
const TOUCH_ON = (typeof window !== 'undefined' && 'ontouchstart' in window) &&
  new URLSearchParams(location.search).get('touch') !== '0';
const T = { x: 0, y: 0, a: false, b: false }; // live touch state: stick vector -1..1, A=shoot, B=jump
const _t = { stickId: null, ax: 0, ay: 0 };
const STICK_R = 56, TDEAD = 0.18;
if (typeof document !== 'undefined' && canvas && canvas.style) canvas.style.touchAction = 'none';
if (TOUCH_ON && typeof document !== 'undefined' && document.createElement) buildTouchUI();
function buildTouchUI() {
  const ui = document.createElement('div');
  ui.id = 'tui';
  ui.style.cssText = 'position:fixed;inset:0;z-index:30;pointer-events:none;touch-action:none;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent;';
  // stick zone: left 50% — touch anywhere, stick anchors under thumb
  const zone = document.createElement('div');
  zone.style.cssText = 'position:absolute;left:0;top:0;width:50%;height:100%;pointer-events:auto;touch-action:none;';
  ui.appendChild(zone);
  const base = document.createElement('div');
  base.style.cssText = 'position:absolute;width:110px;height:110px;border-radius:50%;border:2px solid rgba(255,255,255,.45);background:rgba(255,255,255,.08);display:none;pointer-events:none;transform:translate(-50%,-50%);';
  const knob = document.createElement('div');
  knob.style.cssText = 'position:absolute;width:48px;height:48px;border-radius:50%;background:rgba(255,255,255,.5);display:none;pointer-events:none;transform:translate(-50%,-50%);';
  ui.appendChild(base); ui.appendChild(knob);
  zone.addEventListener('pointerdown', e => {
    if (_t.stickId !== null) return;
    e.preventDefault(); audio();
    _t.stickId = e.pointerId; _t.ax = e.clientX; _t.ay = e.clientY;
    try { zone.setPointerCapture(e.pointerId); } catch (_) {}
    base.style.display = knob.style.display = 'block';
    base.style.left = _t.ax + 'px'; base.style.top = _t.ay + 'px';
    knob.style.left = _t.ax + 'px'; knob.style.top = _t.ay + 'px';
    T.x = 0; T.y = 0;
  });
  zone.addEventListener('pointermove', e => {
    if (e.pointerId !== _t.stickId) return;
    let dx = e.clientX - _t.ax, dy = e.clientY - _t.ay;
    const d = Math.hypot(dx, dy);
    if (d > STICK_R) { dx = dx / d * STICK_R; dy = dy / d * STICK_R; }
    knob.style.left = (_t.ax + dx) + 'px'; knob.style.top = (_t.ay + dy) + 'px';
    let nx = dx / STICK_R, ny = dy / STICK_R;
    if (Math.hypot(nx, ny) < TDEAD) { nx = 0; ny = 0; }
    T.x = nx; T.y = ny;
  });
  const stickUp = e => {
    if (e.pointerId !== _t.stickId) return;
    _t.stickId = null; T.x = 0; T.y = 0;
    base.style.display = knob.style.display = 'none';
  };
  zone.addEventListener('pointerup', stickUp);
  zone.addEventListener('pointercancel', stickUp);
  // action buttons: A = shoot (primary, biggest, bottom-most), B = jump
  function mkBtn(id, label, sub, size, right, bottom) {
    const b = document.createElement('div');
    b.style.cssText = 'position:absolute;right:' + right + 'px;bottom:' + bottom + 'px;width:' + size + 'px;height:' + size + 'px;border-radius:50%;pointer-events:auto;touch-action:none;background:rgba(255,255,255,.12);border:2px solid rgba(255,255,255,.5);color:#fff;font-family:monospace;display:flex;flex-direction:column;align-items:center;justify-content:center;';
    b.innerHTML = '<span style="font-size:' + Math.round(size * 0.34) + 'px;font-weight:bold;line-height:1">' + label + '</span><span style="font-size:9px;opacity:.75">' + sub + '</span>';
    b._ids = new Set();
    b.addEventListener('pointerdown', e => {
      e.preventDefault(); audio();
      b._ids.add(e.pointerId);
      try { b.setPointerCapture(e.pointerId); } catch (_) {}
      T[id] = true;
      b.style.transform = 'scale(.92)'; b.style.background = 'rgba(255,255,255,.30)';
    });
    const off = e => {
      b._ids.delete(e.pointerId);
      if (!b._ids.size) { T[id] = false; b.style.transform = ''; b.style.background = 'rgba(255,255,255,.12)'; }
    };
    b.addEventListener('pointerup', off);
    b.addEventListener('pointercancel', off);
    ui.appendChild(b);
  }
  mkBtn('a', 'A', 'FIRE', 88, 22, 26);
  mkBtn('b', 'B', 'JUMP', 68, 104, 108);
  ui.addEventListener('contextmenu', e => e.preventDefault());
  document.body.appendChild(ui);
}

// ---------- level ----------
const LEVEL_W = 1440;
const GROUND_Y = 230;
// platforms: {x,y,w} — y is top surface
const PLATS = [
  {x:0,y:230,w:500}, {x:550,y:230,w:450}, {x:1050,y:230,w:390},
  {x:180,y:170,w:110}, {x:640,y:160,w:110}, {x:760,y:110,w:110}, {x:1120,y:160,w:90},
];
const PITS = [[500,550],[1000,1050]];
function groundAt(x) {
  for (const p of PLATS) if (x >= p.x && x <= p.x + p.w) return p.y;
  return 9999;
}

// ---------- entities ----------
const hero = { x:40, y:180, vx:0, vy:0, w:20, h:44, face:1, hp:28, maxhp:28, onGround:false, coyote:0, jumpBuf:0, state:'idle', animT:0, shootCd:0, invuln:0, sliding:0 };
let enemies = [], shots = [], eshots = [], parts = [], score = 0, camX = 0, hitstop = 0, shakeT = 0;
let phase = 'ready', readyT = 0, dead = false, winT = 0;

function spawnEnemies() {
  enemies = [
    {type:'walker', x:300, y:0, vx:-0.6, w:22, h:30, hp:2, t:0, minX:220, maxX:460, flash:0},
    {type:'walker', x:700, y:0, vx:0.6, w:22, h:30, hp:2, t:0, minX:600, maxX:940, flash:0},
    {type:'turret', x:790, y:0, vx:0, w:24, h:28, hp:3, t:40, fireT:0, flash:0, py:110},
    {type:'walker', x:1150, y:0, vx:-0.6, w:22, h:30, hp:2, t:0, minX:1100, maxX:1380, flash:0},
    {type:'boss', x:1330, y:0, vx:0, w:40, h:52, hp:12, t:0, fireT:60, flash:0, py:160},
  ];
  for (const e of enemies) { e.y = groundAt(e.x + e.w/2) - e.h; if (e.type==='turret') e.y = e.py - e.h; if (e.type==='boss') e.y = e.py - e.h; }
}

// ---------- drawing helpers ----------
function drawSprite(name, dx, dy, dw, dh, flip) {
  const img = SPR[name]; if (!img || !img.complete) return;
  ctx.save();
  ctx.translate(Math.round(dx + dw/2), Math.round(dy));
  if (flip) ctx.scale(-1, 1);
  ctx.drawImage(img, -dw/2, 0, dw, dh);
  ctx.restore();
}
function drawWalker(e) {
  const x = e.x - camX, y = e.y;
  ctx.fillStyle = '#c03028'; ctx.fillRect(x, y+8, e.w, e.h-8);       // body
  ctx.fillStyle = '#701818'; ctx.fillRect(x, y+8, e.w, 4);
  ctx.fillStyle = '#e8e8e8'; ctx.fillRect(x+4, y+12, 5, 5); ctx.fillRect(x+13, y+12, 5, 5); // eyes
  ctx.fillStyle = '#222'; ctx.fillRect(x+5, y+13, 3, 3); ctx.fillRect(x+14, y+13, 3, 3);
  ctx.fillStyle = '#505050';
  const lp = Math.floor(e.t / 10) % 2;
  ctx.fillRect(x+2+lp*8, y+e.h-6, 6, 6); ctx.fillRect(x+14-lp*8, y+e.h-6, 6, 6); // legs
  if (e.flash > 0) { ctx.fillStyle = 'rgba(255,255,255,0.7)'; ctx.fillRect(x, y, e.w, e.h); }
}
function drawTurret(e) {
  const x = e.x - camX, y = e.y;
  ctx.fillStyle = '#3a3a4a'; ctx.fillRect(x, y+14, e.w, e.h-14);      // base
  ctx.fillStyle = '#70708a'; ctx.fillRect(x+2, y+16, e.w-4, 6);
  const dx = hero.x - e.x, dy = (hero.y+20) - (e.y+8);
  const a = Math.atan2(dy, dx);
  ctx.save(); ctx.translate(x+e.w/2, y+8); ctx.rotate(a);
  ctx.fillStyle = '#20202c'; ctx.fillRect(0, -3, 18, 6);               // barrel
  ctx.restore();
  ctx.fillStyle = '#9090b0'; ctx.fillRect(x+4, y, e.w-8, 12);         // dome
  ctx.fillStyle = '#ff3020'; ctx.fillRect(x+e.w/2-2, y+3, 4, 4);       // eye
  if (e.flash > 0) { ctx.fillStyle = 'rgba(255,255,255,0.7)'; ctx.fillRect(x, y, e.w, e.h); }
}
function drawBoss(e) {
  const x = e.x - camX, y = e.y;
  ctx.fillStyle = '#4a2a3a'; ctx.fillRect(x, y+20, e.w, e.h-20);
  ctx.fillStyle = '#7a4a5a'; ctx.fillRect(x+4, y+24, e.w-8, 8);
  ctx.fillStyle = '#a0a0c0'; ctx.fillRect(x+6, y+2, e.w-12, 22);
  ctx.fillStyle = '#ff3020';
  const blink = Math.floor(e.t / 20) % 2;
  ctx.fillRect(x+10, y+8, 8, 6); ctx.fillRect(x+e.w-18, y+8, 8, 6);
  if (blink) { ctx.fillStyle = '#fff'; ctx.fillRect(x+11, y+9, 3, 3); ctx.fillRect(x+e.w-17, y+9, 3, 3); }
  ctx.fillStyle = '#20202c';
  ctx.fillRect(x-6, y+e.h/2-3, 10, 6); ctx.fillRect(x+e.w-4, y+e.h/2-3, 10, 6);
  if (e.flash > 0) { ctx.fillStyle = 'rgba(255,255,255,0.7)'; ctx.fillRect(x, y, e.w, e.h); }
}
function explode(x, y, color, n) {
  for (let i = 0; i < n; i++) {
    parts.push({x, y, vx:(Math.random()-0.5)*4, vy:(Math.random()-0.5)*4-1, t:30+Math.random()*20, c:color, s:2+Math.random()*2});
  }
}

// ---------- update ----------
function update() {
  if (phase === 'ready') { readyT++; if (readyT > 90) phase = 'play'; return; }
  if (phase === 'over' || phase === 'win') { winT++; return; }
  musicTick();
  const h = hero;

  // --- auto bot ---
  let botShoot = false;
  if (AUTO) {
    keys['ArrowRight'] = true; keys['ArrowLeft'] = false;
    // hold position vs boss at range instead of running in (turrets: keep moving)
    for (const e of enemies) {
      if (e.type === 'boss' && e.x - h.x < 200 && e.x > h.x) {
        keys['ArrowRight'] = false;
      }
    }
    // jump at pits / edges
    const aheadX = h.x + h.w + 26;
    const gAhead = groundAt(aheadX);
    if ((gAhead > h.y + h.h + 30 || aheadX > 495 && aheadX < 560 || aheadX > 995 && aheadX < 1060) && h.onGround) { h.jumpBuf = 6; h._botJumpT = 16; }
    if (h._botJumpT > 0) { h._botJumpT--; keys['ArrowUp'] = true; } else if (AUTO) keys['ArrowUp'] = false;
    // dodge: jump if enemy shot is close (any direction)
    if (AUTO && h.onGround && h._botJumpT <= 0) {
      for (const s of eshots) {
        const dx = s.x - (h.x + h.w/2), dy = s.y - (h.y + 20);
        if (Math.abs(dx) < 70 && Math.abs(dy) < 40) {
          h.jumpBuf = 6; h._botJumpT = 16; break;
        }
      }
    }
    // shoot at nearest enemy ahead
    h.shootCd--;
    let near = null;
    for (const e of enemies) { if (e.x > h.x && e.x - h.x < 220 && (!near || e.x < near.x)) near = e; }
    if (near && h.shootCd <= 0) botShoot = true;
  }

  // --- hero physics ---
  const tL = T.x < -0.35, tR = T.x > 0.35, tU = T.y < -0.35, tD = T.y > 0.35, tA = T.a, tB = T.b;
  const L = pressed('ArrowLeft')||pressed('KeyA')||tL, R = pressed('ArrowRight')||pressed('KeyD')||tR;
  const ACC = 0.5, MAXV = 2.2;
  if (R && !L) { h.vx = Math.min(h.vx + ACC, MAXV); h.face = 1; }
  else if (L && !R) { h.vx = Math.max(h.vx - ACC, -MAXV); h.face = -1; }
  else { h.vx *= 0.8; if (Math.abs(h.vx) < 0.05) h.vx = 0; }

  const J = pressed('ArrowUp')||pressed('KeyW')||pressed('KeyX')||pressed('KeyK')||tB;
  if (J && !h._jheld) { h.jumpBuf = 6; h._jheld = true; }
  if (!J) h._jheld = false;
  if (h.jumpBuf > 0) h.jumpBuf--;
  if (h.coyote > 0) h.coyote--;
  const wantSlide = (pressed('ArrowDown')||pressed('KeyS')||tD) && h.onGround && Math.abs(h.vx) > 1.2;
  if (wantSlide && h.sliding <= 0) { h.sliding = 18; SFX.jump(); }
  if (h.sliding > 0) { h.sliding--; h.vx = h.face * 3.2; }

  if (h.jumpBuf > 0 && (h.onGround || h.coyote > 0) && h.sliding <= 0) {
    h.vy = -10.5; h.onGround = false; h.coyote = 0; h.jumpBuf = 0; SFX.jump();
  }
  if (!J && h.vy < -4) h.vy = -4; // variable jump
  h.vy = Math.min(h.vy + 0.5, 12);

  h.x += h.vx;
  h.y += h.vy;
  h.x = Math.max(4, Math.min(LEVEL_W - h.w - 4, h.x));

  // ground collision
  h.onGround = false;
  const feet = h.y + h.h;
  const g = groundAt(h.x + h.w/2);
  if (h.vy >= 0 && feet >= g && feet <= g + 14 && g < 9000) {
    h.y = g - h.h; h.vy = 0; h.onGround = true; h.coyote = 6;
  }
  if (h.y > 320) { hurtHero(99); } // pit death

  // state
  h.animT++;
  if (h.invuln > 0) h.invuln--;
  if (h.sliding > 0) h.state = 'slide';
  else if (!h.onGround) h.state = 'jump';
  else if (Math.abs(h.vx) > 0.3) h.state = 'run';
  else h.state = 'idle';

  // --- shooting ---
  const SH = pressed('KeyZ')||pressed('KeyJ')||tA;
  if (h.shootCd > 0) h.shootCd--;
  if ((SH && !h._sh) || (tA && h.shootCd <= 0) || botShoot) { // touch A held = rapid fire
    if (h.shootCd <= 0) {
      h.shootCd = 14;
      const up = pressed('ArrowUp')||pressed('KeyW')||tU;
      shots.push({x: h.x + h.w/2 + h.face*14, y: h.y + 18 + (up ? -14 : 0), vx: h.face*6, vy: up ? -2.5 : 0, t: 60});
      if (up) shots[shots.length-1].vy = -2.5;
      parts.push({x: h.x + h.w/2 + h.face*16, y: h.y + 18, vx: h.face*1, vy: 0, t: 5, c: '#ffe060', s: 4});
      SFX.shoot();
      if (h.onGround) h.state = up ? 'shoot_up' : 'shoot', h.animT = 0;
    }
  }
  h._sh = SH;

  // --- shots ---
  for (let i = shots.length-1; i >= 0; i--) {
    const s = shots[i]; s.x += s.vx; s.y += s.vy; s.t--;
    let dead2 = s.t <= 0 || s.x < camX - 20 || s.x > camX + W + 20;
    if (!dead2) for (let j = enemies.length-1; j >= 0; j--) {
      const e = enemies[j];
      if (s.x > e.x && s.x < e.x + e.w && s.y > e.y && s.y < e.y + e.h) {
        e.hp--; e.flash = 5; dead2 = true;
        explode(s.x, s.y, '#ffe060', 4);
        if (e.hp <= 0) {
          explode(e.x+e.w/2, e.y+e.h/2, e.type==='boss' ? '#ff6020' : '#c0c0d0', e.type==='boss' ? 40 : 16);
          SFX.explode(); score += e.type==='boss' ? 1000 : e.type==='turret' ? 200 : 100;
          enemies.splice(j, 1);
          hitstop = 3;
          if (e.type === 'boss') { phase = 'win'; winT = 0; }
        } else SFX.shoot();
        break;
      }
    }
    if (dead2) shots.splice(i, 1);
  }

  // --- enemies ---
  for (const e of enemies) {
    e.t++;
    if (e.flash > 0) e.flash--;
    if (e.type === 'walker') {
      e.x += e.vx;
      if (e.x < e.minX || e.x + e.w > e.maxX) e.vx *= -1;
      e.y = groundAt(e.x + e.w/2) - e.h;
    } else if (e.type === 'turret' || e.type === 'boss') {
      e.fireT--;
      const dx = h.x - e.x, dy = h.y - e.y, d = Math.hypot(dx, dy);
      if (e.fireT <= 0 && d < 320 && d > 30) {
        e.fireT = e.type === 'boss' ? 70 : 110;
        const sp = 2.4, n = e.type === 'boss' ? 3 : 1;
        for (let k = 0; k < n; k++) {
          const a = Math.atan2(dy, dx) + (k - (n-1)/2) * 0.25;
          eshots.push({x: e.x + e.w/2, y: e.y + 10, vx: Math.cos(a)*sp, vy: Math.sin(a)*sp, t: 200});
        }
        SFX.eshoot();
      }
    }
    // touch damage
    if (h.invuln <= 0 && h.sliding <= 0 &&
        h.x < e.x + e.w && h.x + h.w > e.x && h.y < e.y + e.h && h.y + h.h > e.y) {
      hurtHero(4);
    }
  }

  // --- enemy shots ---
  for (let i = eshots.length-1; i >= 0; i--) {
    const s = eshots[i]; s.x += s.vx; s.y += s.vy; s.t--;
    let gone = s.t <= 0 || s.x < camX - 20 || s.x > camX + W + 20 || s.y > 300;
    if (!gone && h.invuln <= 0 &&
        s.x > h.x && s.x < h.x + h.w && s.y > h.y && s.y < h.y + h.h) {
      hurtHero(4); gone = true;
    }
    if (gone) eshots.splice(i, 1);
  }

  // --- particles ---
  for (let i = parts.length-1; i >= 0; i--) {
    const p = parts[i]; p.x += p.vx; p.y += p.vy; p.vy += 0.15; p.t--;
    if (p.t <= 0) parts.splice(i, 1);
  }

  // camera
  camX = Math.max(0, Math.min(LEVEL_W - W, h.x + h.w/2 - W*0.42));
}
function hurtHero(d) {
  const h = hero;
  if (h.invuln > 0 || phase !== 'play') return;
  h.hp -= d; h.invuln = 60; h.state = 'hit'; h.animT = 0;
  SFX.hurt();
  explode(h.x + h.w/2, h.y + h.h/2, '#ff4040', 8);
  if (h.hp <= 0) { phase = 'over'; winT = 0; SFX.explode(); explode(h.x+10, h.y+20, '#60a0ff', 30); }
}

// ---------- render ----------
function render() {
  // bg parallax
  if (bgImg.complete && bgImg.naturalWidth) {
    const bw = 960, bh = 540;
    let off = -(camX * 0.3 % bw);
    for (let x = off - bw; x < W; x += bw) ctx.drawImage(bgImg, x, -140, bw, bh);
    ctx.fillStyle = 'rgba(8,8,20,0.45)'; ctx.fillRect(0, 0, W, H);
  } else { ctx.fillStyle = '#0a0a18'; ctx.fillRect(0, 0, W, H); }

  // platforms
  for (const p of PLATS) {
    const x = p.x - camX;
    if (x + p.w < 0 || x > W) continue;
    ctx.fillStyle = '#2a2a3a'; ctx.fillRect(x, p.y, p.w, H - p.y);
    ctx.fillStyle = '#4a4a6a'; ctx.fillRect(x, p.y, p.w, 6);
    ctx.fillStyle = '#1a1a28';
    for (let bx = x + 8; bx < x + p.w - 4; bx += 24) ctx.fillRect(bx, p.y + 8, 3, 3);
    ctx.fillStyle = '#c06020';
    for (let bx = x + 4; bx < x + p.w; bx += 40) ctx.fillRect(bx, p.y + 2, 12, 2);
  }

  // goal gate
  const gx = 1400 - camX;
  if (gx > -40 && gx < W + 40) {
    ctx.fillStyle = '#20202c'; ctx.fillRect(gx, 150, 24, 80);
    ctx.fillStyle = '#30e080'; ctx.fillRect(gx + 4, 154, 16, 20);
    ctx.fillStyle = '#e8e8e8'; ctx.font = '8px monospace'; ctx.fillText('EXIT', gx - 2, 145);
  }

  // enemy shots
  for (const s of eshots) {
    ctx.fillStyle = '#ff3040';
    ctx.beginPath(); ctx.arc(s.x - camX, s.y, 4, 0, 7); ctx.fill();
    ctx.fillStyle = '#ffb0b0'; ctx.beginPath(); ctx.arc(s.x - camX, s.y, 2, 0, 7); ctx.fill();
  }
  // player shots
  for (const s of shots) {
    ctx.fillStyle = '#80e0ff'; ctx.fillRect(s.x - camX - 5, s.y - 2, 10, 4);
    ctx.fillStyle = '#ffffff'; ctx.fillRect(s.x - camX - 2, s.y - 1, 5, 2);
  }
  // enemies
  for (const e of enemies) {
    if (e.type === 'walker') drawWalker(e);
    else if (e.type === 'turret') drawTurret(e);
    else drawBoss(e);
  }
  // hero
  const h = hero;
  if (!(h.invuln > 0 && Math.floor(h.invuln / 4) % 2 === 0) || phase !== 'play') {
    const hx = h.x - camX, hw = 25, hh = 50;
    const flip = h.face < 0;
    let spr = 'idle';
    if (h.state === 'run') spr = 'run' + (1 + Math.floor(h.animT / 8) % 2);
    else if (h.state === 'jump') spr = 'jump';
    else if (h.state === 'slide') spr = 'slide';
    else if (h.state === 'hit') spr = 'hit';
    else if (h.state === 'shoot') spr = 'shoot';
    else if (h.state === 'shoot_up') spr = 'shoot_up';
    if (spritesReady && SPR[spr]) drawSprite(spr, hx + h.w/2 - hw/2, h.y + h.h - hh, hw, hh, flip);
    else { ctx.fillStyle = '#3080f0'; ctx.fillRect(hx, h.y, h.w, h.h); }
  }
  // particles
  for (const p of parts) {
    ctx.fillStyle = p.c; ctx.globalAlpha = Math.min(1, p.t / 20);
    ctx.fillRect(p.x - camX - p.s/2, p.y - p.s/2, p.s, p.s);
    ctx.globalAlpha = 1;
  }

  // HUD
  ctx.fillStyle = 'rgba(0,0,0,0.55)'; ctx.fillRect(0, 0, W, 22);
  ctx.fillStyle = '#e8e8e8'; ctx.font = '10px monospace';
  ctx.fillText('SCORE ' + score, 8, 15);
  // hp bar
  ctx.fillStyle = '#401010'; ctx.fillRect(200, 6, 120, 10);
  const hpr = Math.max(0, h.hp / h.maxhp);
  ctx.fillStyle = hpr > 0.5 ? '#30e060' : hpr > 0.25 ? '#e0a030' : '#e03030';
  ctx.fillRect(200, 6, 120 * hpr, 10);
  ctx.fillStyle = '#e8e8e8'; ctx.fillText('HP', 178, 15);
  if (AUTO) { ctx.fillStyle = '#808080'; ctx.fillText('AUTO', 440, 15); }

  if (phase === 'ready') {
    ctx.fillStyle = 'rgba(0,0,0,0.6)'; ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#ffe060'; ctx.font = '28px monospace'; ctx.textAlign = 'center';
    ctx.fillText('READY', W/2, H/2 - 10);
    ctx.fillStyle = '#e8e8e8'; ctx.font = '10px monospace';
    ctx.fillText(TOUCH_ON ? 'LEFT STICK MOVE · A FIRE · B JUMP · DOWN+B SLIDE' : 'ARROWS MOVE · Z SHOOT · X JUMP · DOWN+JUMP SLIDE', W/2, H/2 + 16);
    ctx.textAlign = 'left';
  } else if (phase === 'over') {
    ctx.fillStyle = 'rgba(0,0,0,0.7)'; ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#ff4040'; ctx.font = '28px monospace'; ctx.textAlign = 'center';
    ctx.fillText('GAME OVER', W/2, H/2);
    ctx.fillStyle = '#e8e8e8'; ctx.font = '10px monospace';
    ctx.fillText('SCORE ' + score, W/2, H/2 + 22);
    ctx.textAlign = 'left';
  } else if (phase === 'win') {
    ctx.fillStyle = 'rgba(0,0,0,0.6)'; ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#30e080'; ctx.font = '28px monospace'; ctx.textAlign = 'center';
    ctx.fillText('STAGE CLEAR!', W/2, H/2 - 8);
    ctx.fillStyle = '#ffe060'; ctx.font = '12px monospace';
    ctx.fillText('SCORE ' + score, W/2, H/2 + 18);
    ctx.textAlign = 'left';
  }
}

// ---------- main loop ----------
let last = 0;
function frame(t) {
  requestAnimationFrame(frame);
  if (hitstop > 0) { hitstop--; render(); return; }
  update();
  render();
}
loadSprites();
spawnEnemies();
requestAnimationFrame(frame);
